contracts/FormulationRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

contract FormulationRegistry {
    struct Formulation {
        uint256 formulationId;
        string name;
        string[] sourceBatchIds;
        string qrCodeUrl;
        uint256 timestamp;
        address registrar;
    }

    mapping(uint256 => Formulation) public formulations;

    event FormulationRegistered(
        uint256 indexed formulationId,
        string name,
        string qrCodeUrl,
        uint256 timestamp,
        address indexed registrar
    );

    function registerFormulation(
        uint256 _formulationId,
        string memory _name,
        string[] memory _sourceBatchIds,
        string memory _qrCodeUrl
    ) external {
        require(formulations[_formulationId].formulationId == 0, "Formulation already registered");

        formulations[_formulationId] = Formulation({
            formulationId: _formulationId,
            name: _name,
            sourceBatchIds: _sourceBatchIds,
            qrCodeUrl: _qrCodeUrl,
            timestamp: block.timestamp,
            registrar: msg.sender
        });

        emit FormulationRegistered(
            _formulationId,
            _name,
            _qrCodeUrl,
            block.timestamp,
            msg.sender
        );
    }

    function getFormulationBatches(uint256 _formulationId) external view returns (string[] memory) {
        return formulations[_formulationId].sourceBatchIds;
    }
}

contracts/GeoFenceValidator.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

contract GeoFenceValidator {
    address public admin;

    // species => hash of approved zone (GeoJSON or boundary points)
    mapping(string => string) public approvedZones;

    event ZoneUpdated(string indexed species, string zoneHash, address indexed updater);

    modifier onlyAdmin() {
        require(msg.sender == admin, "Not admin");
        _;
    }

    constructor() {
        admin = msg.sender;
    }

    function setApprovedZone(string memory _species, string memory _zoneHash) external onlyAdmin {
        approvedZones[_species] = _zoneHash;
        emit ZoneUpdated(_species, _zoneHash, msg.sender);
    }

    function getApprovedZone(string memory _species) external view returns (string memory) {
        return approvedZones[_species];
    }
}

contracts/HarvestRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

contract HarvestRegistry {
    struct Harvest {
        string batchId;
        string species;
        string gpsHash; // Or coordinates, hashed for privacy/immutability
        bool zoneValidated;
        uint256 timestamp;
        address registrar;
    }

    mapping(string => Harvest) public harvests;

    event HarvestRegistered(
        string indexed batchId,
        string species,
        string gpsHash,
        bool zoneValidated,
        uint256 timestamp,
        address indexed registrar
    );

    function registerHarvest(
        string memory _batchId,
        string memory _species,
        string memory _gpsHash,
        bool _zoneValidated
    ) external {
        require(bytes(harvests[_batchId].batchId).length == 0, "Harvest already registered");

        harvests[_batchId] = Harvest({
            batchId: _batchId,
            species: _species,
            gpsHash: _gpsHash,
            zoneValidated: _zoneValidated,
            timestamp: block.timestamp,
            registrar: msg.sender
        });

        emit HarvestRegistered(
            _batchId,
            _species,
            _gpsHash,
            _zoneValidated,
            block.timestamp,
            msg.sender
        );
    }
}

contracts/HerbTraceability.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

contract HerbTraceability {
    enum BatchState { Collected, Aggregated, Testing, Tested, Processed, Distributed }

    struct Batch {
        string batchId; // IPFS hash or UUID from off-chain
        address currentOwner;
        address collector;
        BatchState state;
        uint256 timestamp;
    }

    mapping(string => Batch) public batches;
    mapping(address => bool) public authorizedLabs;

    event BatchRegistered(string indexed batchId, address indexed collector, uint256 timestamp);
    event BatchStateChanged(string indexed batchId, BatchState newState, address indexed updater, uint256 timestamp);
    event OwnershipTransferred(string indexed batchId, address indexed previousOwner, address indexed newOwner, uint256 timestamp);
    event LabAuthorized(address indexed lab);
    event LabRevoked(address indexed lab);

    address public admin;

    modifier onlyAdmin() {
        require(msg.sender == admin, "Not admin");
        _;
    }

    modifier onlyBatchOwner(string memory _batchId) {
        require(batches[_batchId].currentOwner == msg.sender, "Not batch owner");
        _;
    }

    constructor() {
        admin = msg.sender;
    }

    function authorizeLab(address _lab) external onlyAdmin {
        authorizedLabs[_lab] = true;
        emit LabAuthorized(_lab);
    }

    function revokeLab(address _lab) external onlyAdmin {
        authorizedLabs[_lab] = false;
        emit LabRevoked(_lab);
    }

    function registerBatch(string memory _batchId) external {
        require(batches[_batchId].currentOwner == address(0), "Batch already exists");

        batches[_batchId] = Batch({
            batchId: _batchId,
            currentOwner: msg.sender,
            collector: msg.sender,
            state: BatchState.Collected,
            timestamp: block.timestamp
        });

        emit BatchRegistered(_batchId, msg.sender, block.timestamp);
    }

    function transferOwnership(string memory _batchId, address _newOwner) external onlyBatchOwner(_batchId) {
        require(_newOwner != address(0), "Invalid address");

        address previousOwner = batches[_batchId].currentOwner;
        batches[_batchId].currentOwner = _newOwner;

        emit OwnershipTransferred(_batchId, previousOwner, _newOwner, block.timestamp);
    }

    function updateBatchState(string memory _batchId, BatchState _newState) external {
        Batch storage batch = batches[_batchId];
        require(batch.currentOwner != address(0), "Batch does not exist");

        // Only the owner or an authorized lab (if testing) can update the state
        if (_newState == BatchState.Tested) {
            require(authorizedLabs[msg.sender], "Only authorized labs can mark as Tested");
        } else {
            require(msg.sender == batch.currentOwner, "Not authorized to update state");
        }

        batch.state = _newState;
        batch.timestamp = block.timestamp;

        emit BatchStateChanged(_batchId, _newState, msg.sender, block.timestamp);
    }
}

